            $items = $category ? array_values(array_filter($products, fn ($p) => in_array((int) ($category['id'] ?? 0), array_map('intval', (array) ($p['category_ids'] ?? [])), true))) : [];
            foreach (array_slice($items, 0, $limit) as $p) {
