                $headerPrimary = e((string) ($primaryThemeForHeader['palette']['primary'] ?? $headerGradient['from'] ?? '#0f766e'));
                $headerGradientFrom = e((string) ($headerGradient['from'] ?? '#0f766e'));
                $headerGradientVia = e((string) ($headerGradient['via'] ?? $headerGradient['from'] ?? '#0f766e'));
                $headerGradientTo = e((string) ($headerGradient['to'] ?? $headerGradient['via'] ?? '#115e59'));
                $headerGradientGlow = e((string) ($headerGradient['glow'] ?? $headerGradient['via'] ?? '#14b8a6'));
                $overlayLogoSurfaceStyle = '';
                $whiteCtaHeader = $overlayHeader || $headerVariantType === 'primary_header';
                $overlayCtaInlineStyle = $customShell
                    ? "background:{$customCtaBg};background-color:{$customCtaBg};border:0;color:{$customCtaColor};-webkit-text-fill-color:{$customCtaColor};border-radius:{$customCtaRadius}px;box-shadow:none"
                    : ($whiteCtaHeader
                        ? "background:#fff;background-color:#fff;border:1px solid #fff;color:{$headerPrimary};-webkit-text-fill-color:{$headerPrimary};box-shadow:none"
                        : "background:{$headerPrimary};background-color:{$headerPrimary};border:1px solid {$headerPrimary};color:{$headerPrimaryText};-webkit-text-fill-color:{$headerPrimaryText};box-shadow:none");
                $showHeaderCta = ! in_array($headerVariantType, ['centered_header','overlay_centered_header'], true);
                $splitHeaderLayout = in_array($headerVariantType, ['centered_header','split_navigation_header','overlay_centered_header'], true);

                $renderDesktopMenu = function (array $items, int $depth = 0) use (&$renderDesktopMenu, $menuText, $customMenuInlineStyle): string {
                    $itemsHtml = '';

                    foreach ($items as $item) {
                        if (! is_array($item)) continue;

                        $url = e($item['url'] ?? '#');
                        $label = e($item['label'] ?? '');
                        $children = is_array($item['children'] ?? null) ? $item['children'] : [];
                        $hasChildren = count($children) > 0;
                        $dropdown = '';

                        if ($hasChildren) {
                            // The wrapper touches its parent; inner padding creates visual space
                            // without introducing a hover gap that closes the submenu.
                            $dropdownPosition = $depth > 0
                                ? 'left-full top-0 pl-2'
                                : 'left-0 top-full pt-2';
                            $borderClass = $depth > 0 ? 'border-slate-300' : 'border-slate-200';
                            $dropdown = "<div class='menu-dropdown absolute {$dropdownPosition} z-50 min-w-52'>"
                                . "<ul class='list-none rounded-xl border {$borderClass} bg-white p-2 shadow-2xl ring-1 ring-slate-950/5'>"
                                . $renderDesktopMenu($children, $depth + 1)
                                . "</ul></div>";
                        }

                        $menuClass = $hasChildren ? "menu-node menu-depth-{$depth} relative" : 'menu-leaf';
                        $linkStyle = $depth > 0 ? 'color:#0f172a;' : $customMenuInlineStyle;
                        $linkClass = $depth > 0 ? 'text-slate-800' : $menuText;
                        $itemsHtml .= "<li class='{$menuClass}'>"
                            . "<a href='{$url}' style='{$linkStyle}' class='{$linkClass} flex items-center gap-1 whitespace-nowrap transition hover:opacity-80'>{$label}" . ($hasChildren ? "<span aria-hidden='true' class='text-xs'>⌄</span>" : '') . "</a>"
                            . $dropdown
                            . "</li>";
                    }

                    return $itemsHtml;
                };

                $mobileMenuCounter = 0;
                $renderMobileMenu = function (array $items, int $depth = 0) use (&$renderMobileMenu, &$mobileMenuCounter): string {
                    $itemsHtml = '';

                    foreach ($items as $item) {
                        if (! is_array($item)) continue;

                        $url = e($item['url'] ?? '#');
                        $label = e($item['label'] ?? '');
                        $children = is_array($item['children'] ?? null) ? $item['children'] : [];
                        $hasChildren = count($children) > 0;
                        $indent = min($depth, 3) * 16;

                        if (! $hasChildren) {
                            $itemsHtml .= "<li>"
                                . "<a data-cosmic-mobile-link href='{$url}' class='block rounded-xl px-3 py-3 text-base font-semibold text-slate-800 transition hover:bg-slate-100' style='margin-left: {$indent}px'>{$label}</a>"
                                . "</li>";
                            continue;
                        }

                        $mobileMenuCounter++;
                        $submenuId = 'cosmic-mobile-submenu-' . $mobileMenuCounter;
                        $itemsHtml .= "<li class='border-b border-slate-200/80 py-1 last:border-b-0'>"
                            . "<div class='flex items-center gap-2' style='margin-left: {$indent}px'>"
                            . "<a data-cosmic-mobile-link href='{$url}' class='min-w-0 flex-1 rounded-xl px-3 py-3 text-base font-semibold text-slate-900 transition hover:bg-slate-100'>{$label}</a>"
                            . "<button type='button' class='cosmic-mobile-submenu-toggle inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-xl text-slate-600 transition hover:bg-slate-100 hover:text-slate-950' aria-expanded='false' aria-controls='{$submenuId}' aria-label='Toggle {$label} submenu'>"
                            . "<svg aria-hidden='true' viewBox='0 0 24 24' class='h-5 w-5 transition-transform duration-200'><path d='m7 10 5 5 5-5' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/></svg>"
                            . "</button>"
                            . "</div>"
                            . "<ul id='{$submenuId}' class='cosmic-mobile-submenu hidden list-none space-y-1 pb-3 pt-1'>"
                            . $renderMobileMenu($children, $depth + 1)
                            . "</ul>"
                            . "</li>";
                    }

                    return $itemsHtml;
                };

                $normalizedMenuItems = is_array($menuItems) ? array_values($menuItems) : [];
                $desktopNavHtml = $renderDesktopMenu($normalizedMenuItems);
                $mobileNavHtml = $renderMobileMenu($normalizedMenuItems);
                $menuHalf = (int) ceil(count($normalizedMenuItems) / 2);
                $desktopNavLeftHtml = $renderDesktopMenu(array_slice($normalizedMenuItems, 0, $menuHalf));
                $desktopNavRightHtml = $renderDesktopMenu(array_slice($normalizedMenuItems, $menuHalf));
                $desktopCtaHtml = $showHeaderCta ? "<a href='{$ctaUrl}' class='cosmic-primary-cta shrink-0 rounded-full px-7 py-3 text-sm font-semibold transition hover:opacity-90' style='{$overlayCtaInlineStyle}'>{$ctaLabel}</a>" : '';
                $desktopPhoneHtml = $customPhoneEnabled ? "<span style='color:{$customNavColor};font-size:{$customNavSize}px' class='hidden shrink-0 items-center gap-2 font-semibold lg:inline-flex'><span aria-hidden='true'>☎</span>".e($customPhone)."</span>" : '';
                $logoLinkColor = $customShell ? $customHeaderText : $headerSurfaceText;
                $logoLinkHtml = "<a href='/' class='relative z-[72] text-xl font-extrabold tracking-wide' style='color:{$logoLinkColor}' aria-label='{$logoText} home'>{$logo}</a>";
                if ($splitHeaderLayout) {
                    $desktopHeaderInner = "<div class='hidden w-full grid-cols-[1fr_auto_1fr] items-center gap-8 md:grid'><nav class='min-w-0 justify-self-start' aria-label='Primary navigation left'><ul class='m-0 flex list-none items-center gap-7 p-0 lg:gap-9'>{$desktopNavLeftHtml}</ul></nav><div class='justify-self-center'>{$logoLinkHtml}</div><div class='flex min-w-0 items-center justify-self-end gap-6'><nav aria-label='Primary navigation right'><ul class='m-0 flex list-none items-center gap-7 p-0 lg:gap-9'>{$desktopNavRightHtml}</ul></nav>{$desktopPhoneHtml}{$desktopCtaHtml}</div></div>";
                } else {
                    $desktopHeaderInner = "<div class='hidden w-full items-center justify-between gap-8 md:flex'>{$logoLinkHtml}<nav class='ml-auto flex min-w-0 items-center gap-8' aria-label='Primary navigation'><ul class='m-0 flex list-none items-center gap-7 p-0 lg:gap-9 xl:gap-10'>{$desktopNavHtml}</ul>{$desktopPhoneHtml}{$desktopCtaHtml}</nav></div>";
                }

                $html .= "
                <style>
                    .cosmic-static-header .menu-node > a > span[aria-hidden='true'] { display: none; }
                    .cosmic-header-variant-centered { flex-wrap:wrap; justify-content:center !important; text-align:center; }
                    .cosmic-header-variant-centered > a { width:100%; display:flex; justify-content:center; }
                    .cosmic-header-variant-centered > nav { margin-left:auto; margin-right:auto; }
                    .cosmic-header-variant-split-navigation > a { order:2; position:absolute; left:50%; transform:translateX(-50%); }
                    .cosmic-header-variant-split-navigation > nav { order:3; margin-left:auto; }
                    .cosmic-header-variant-floating-glass { width:calc(100% - 2rem) !important; max-width:1480px; margin:1rem auto 0; border:1px solid rgba(148,163,184,.28) !important; border-radius:1rem; background:rgba(255,255,255,.82) !important; -webkit-backdrop-filter:blur(18px); backdrop-filter:blur(18px); box-shadow:0 18px 55px rgba(15,23,42,.12); }
                    .cosmic-header-variant-minimal { box-shadow:none !important; border-bottom-color:rgba(148,163,184,.18) !important; }
                    @media(max-width:767px){ .cosmic-header-variant-split-navigation > a { position:static; transform:none; order:0; } .cosmic-header-variant-centered > a { width:auto; } .cosmic-header-variant-centered { justify-content:space-between !important; text-align:left; } }
                    .cosmic-static-header .menu-node > a::after {
                        content: '';
                        width: .35rem;
                        height: .35rem;
                        margin-left: .2rem;
                        border-right: 1.5px solid currentColor;
                        border-bottom: 1.5px solid currentColor;
                        transform: rotate(45deg) translateY(-2px);
                        transition: transform .2s ease;
                    }
                    .cosmic-static-header .menu-node:hover > a::after,
                    .cosmic-static-header .menu-node:focus-within > a::after {
                        transform: rotate(225deg) translate(-1px, -1px);
                    }
                    .cosmic-static-header .menu-node > .menu-dropdown { display: none; }
                    .cosmic-static-header .menu-node:hover > .menu-dropdown,
                    .cosmic-static-header .menu-node:focus-within > .menu-dropdown { display: block; }
                    .cosmic-static-header .menu-dropdown > ul > li > a {
                        display: flex;
                        padding: .65rem .8rem;
                        border-radius: .65rem;
                    }
                    .cosmic-static-header .menu-dropdown > ul > li > a:hover {
                        background: rgb(241 245 249);
                    }
                    .cosmic-mobile-overlay {
                        opacity: 0;
                        visibility: hidden;
                        transition: opacity .28s ease, visibility .28s ease;
                    }
                    .cosmic-mobile-panel {
                        transform: translateX(100%);
                        transition: transform .32s cubic-bezier(.22, 1, .36, 1);
                    }
                    .cosmic-mobile-nav-open .cosmic-mobile-overlay {
                        opacity: 1;
                        visibility: visible;
                    }
                    .cosmic-mobile-nav-open .cosmic-mobile-panel { transform: translateX(0); }
                    .cosmic-mobile-submenu-toggle[aria-expanded='true'] svg { transform: rotate(180deg); }
                    body.cosmic-mobile-menu-locked { overflow: hidden; }
                    @media (min-width: 768px) {
                        .cosmic-mobile-overlay,
                        .cosmic-mobile-panel { display: none !important; }
                    }
                    /* Viewport-aware sizing for full Hero Sparks only. Keep mini heroes and
                       ordinary sections content-sized. A solid header consumes viewport space;
                       an overlay header lives inside the hero and therefore uses the full viewport. */
                    :root {
                        --cosmic-hero-fold-height: calc(100vh - var(--cosmic-header-flow-offset, 0px));
                    }
                    section[data-cosmic-block-type^='hero_'],
                    section[data-type^='hero_']:not(.cosmic-motion4-tall) {
                        box-sizing: border-box;
                        min-height: var(--cosmic-hero-fold-height) !important;
                        height: var(--cosmic-hero-fold-height) !important;
                        max-height: var(--cosmic-hero-fold-height) !important;
                        overflow: hidden;
                        padding-top: clamp(3.5rem, 6.5vh, 6rem) !important;
                        padding-bottom: clamp(3.5rem, 6.5vh, 6rem) !important;
                        display: flex;
                        align-items: center;
                    }
                    section[data-cosmic-block-type^='hero_'] > .relative { width: 100%; }
                    /* Full-bleed image/video/motion heroes own their internal spacing.
                       Do not inject generic top/bottom section padding around the media canvas. */
                    section[data-cosmic-block-type^='hero_'].cosmic-hero-media-edge {
                        padding-top: 0 !important;
                        padding-bottom: 0 !important;
                    }
                    @supports (height: 100svh) {
                        :root {
                            --cosmic-hero-fold-height: calc(100svh - var(--cosmic-header-flow-offset, 0px));
                        }
                    }
                    @media (max-width: 767px) {
                        section[data-cosmic-block-type^='hero_'],
                        section[data-type^='hero_']:not(.cosmic-motion4-tall) {
                            min-height: calc(100svh - var(--cosmic-header-flow-offset, 0px)) !important;
                            height: auto !important;
                            max-height: none !important;
                            padding-top: clamp(3.25rem, 7vh, 5rem) !important;
                            padding-bottom: clamp(3.25rem, 7vh, 5rem) !important;
                        }
                    }
                    .cosmic-static-overlay-header {
                        position: absolute !important;
                        background: transparent !important;
                        border-bottom-color: transparent !important;
                        box-shadow: none !important;
                        -webkit-backdrop-filter: blur(3px);
                        backdrop-filter: blur(3px);
                    }
                    .cosmic-static-overlay-first-spark {
                        /* This class is attached to the actual first section, never its
                           outer render shell, so video/image media starts behind header. */
                        padding-top: calc(var(--cosmic-overlay-header-height, 80px) + clamp(4.5rem, 6vw, 6.5rem)) !important;
                    }
                    @media (max-width: 639px) {
                        .cosmic-static-overlay-first-spark {
                            padding-top: calc(var(--cosmic-overlay-header-height, 72px) + 3.25rem) !important;
                        }
                    }
                    /* Contrast-aware overlay header. Runtime selects a light or dark
                       navigation/logo treatment from the first Spark, while CTA keeps
                       the site's primary brand color unless that would merge into a
                       same-primary hero. */
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-tone-light > a {
                        color: #fff !important;
                    }
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'] > a {
                        color: #fff !important;
                        background: transparent !important;
                        border: 0 !important;
                        padding: 0 !important;
                        box-shadow: none !important;
                        -webkit-backdrop-filter: none !important;
                        backdrop-filter: none !important;
                    }
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-tone-light > nav > ul > li > a {
                        color: #fff !important;
                    }
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-tone-light > nav > ul > li > a:hover {
                        color: rgba(255,255,255,.82) !important;
                    }
                    .cosmic-static-overlay-header.cosmic-overlay-tone-dark > nav > ul > li > a {
                        color: #0f172a !important;
                    }
                    .cosmic-static-overlay-header.cosmic-overlay-tone-dark > nav > ul > li > a:hover {
                        color: #020617 !important;
                    }
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-cta-gradient > nav > a.cosmic-primary-cta,
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-cta-gradient > nav > a.cosmic-primary-cta * {
                        color:#fff !important;
                        -webkit-text-fill-color:#fff !important;
                    }
                    header.cosmic-static-header.cosmic-static-overlay-header[data-cosmic-premium-overlay-header='true'].cosmic-overlay-cta-gradient > nav > a.cosmic-primary-cta {
                        background:{$headerPrimary} !important;
                        background-color:{$headerPrimary} !important;
                        border:1px solid {$headerPrimary} !important;
                        box-shadow:none !important;
                    }
                    .cosmic-static-overlay-header.cosmic-overlay-cta-primary > nav > a {
                        box-shadow:none !important;
                    }
                </style>

                <header data-cosmic-overlay-header='" . ($overlayHeader ? "true" : "false") . "' data-cosmic-page-style='" . e(self::$currentPageStyle) . "' data-cosmic-primary-overlay-allowed='" . ($overlayPrimaryAllowed ? "true" : "false") . "' data-cosmic-premium-overlay-header='" . ($premiumOverlayHeader ? "true" : "false") . "' data-cosmic-header-variant='{$headerVariantType}' style='{$customHeaderInlineStyle}' class='cosmic-static-header {$headerVariantClass} {$overlayHeaderClass} z-50 w-full {$headerDividerClass} px-6 py-4 sm:px-[50px]'>
                    {$desktopHeaderInner}
                    <div class='flex w-full items-center justify-between gap-5 md:hidden'>
                        {$logoLinkHtml}
                        <button
                            type='button'
                            class='cosmic-mobile-menu-open relative z-[72] inline-flex h-12 w-12 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-900 shadow-sm transition hover:bg-slate-50'
                            aria-expanded='false'
                            aria-controls='cosmic-mobile-panel'
                            aria-label='Open navigation menu'
                        >
                            <svg aria-hidden='true' viewBox='0 0 24 24' class='h-6 w-6'><path d='M4 7h16M4 12h16M4 17h16' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round'/></svg>
                        </button>
                    </div>
                </header>

                <div class='cosmic-mobile-navigation md:hidden' aria-hidden='true'>
                    <button type='button' class='cosmic-mobile-overlay fixed inset-0 z-[68] cursor-default bg-slate-950/60 backdrop-blur-[2px]' aria-label='Close navigation menu'></button>

                    <aside id='cosmic-mobile-panel' class='cosmic-mobile-panel fixed inset-y-0 right-0 z-[70] flex w-[min(88vw,390px)] flex-col bg-white shadow-[-24px_0_70px_rgba(15,23,42,.22)]' role='dialog' aria-modal='true' aria-label='Mobile navigation'>
                        <div class='flex items-center justify-between border-b border-slate-200 px-6 py-5'>
                            <span class='text-xs font-bold uppercase tracking-[.24em] text-slate-500'>Navigation</span>
                            <button type='button' class='cosmic-mobile-menu-close inline-flex h-11 w-11 items-center justify-center rounded-full border border-slate-200 text-slate-700 transition hover:bg-slate-100 hover:text-slate-950' aria-label='Close navigation menu'>
                                <svg aria-hidden='true' viewBox='0 0 24 24' class='h-5 w-5'><path d='m6 6 12 12M18 6 6 18' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round'/></svg>
                            </button>
                        </div>

                        <div class='flex-1 overflow-y-auto px-5 py-5'>
                            <ul class='m-0 list-none space-y-1 p-0'>
                                {$mobileNavHtml}
                            </ul>
                        </div>

                        <div class='border-t border-slate-200 bg-slate-50 px-6 py-6'>
                            <a data-cosmic-mobile-link href='{$ctaUrl}' class='cosmic-primary-cta {$buttonBg} {$buttonText} flex w-full items-center justify-center rounded-full px-7 py-4 text-center text-sm font-semibold shadow-lg transition hover:opacity-90' style='background:var(--p,var(--cosmic-primary,#243447));background-color:var(--p,var(--cosmic-primary,#243447));border-color:var(--p,var(--cosmic-primary,#243447));color:#fff;-webkit-text-fill-color:#fff'>
                                {$ctaLabel}
                            </a>
                        </div>
                    </aside>
                </div>

                <script>
                    (() => {
                        const initCosmicStaticHeader = () => {
                        const anyStaticHeader = document.querySelector('.cosmic-static-header');
                        if (anyStaticHeader) {
                            const syncHeaderFlowOffset = () => {
                                const overlaysHero = anyStaticHeader.dataset.cosmicOverlayHeader === 'true';
                                const headerHeight = Math.ceil(anyStaticHeader.getBoundingClientRect().height || 0);
                                document.documentElement.style.setProperty('--cosmic-header-flow-offset', overlaysHero ? '0px' : `\${headerHeight}px`);
                            };
                            syncHeaderFlowOffset();
                            window.addEventListener('resize', syncHeaderFlowOffset);
                            if (typeof ResizeObserver !== 'undefined') {
                                const headerFlowResizeObserver = new ResizeObserver(syncHeaderFlowOffset);
                                headerFlowResizeObserver.observe(anyStaticHeader);
                            }
                        }

                        const staticHeader = document.querySelector('.cosmic-static-header[data-cosmic-overlay-header=\"true\"]');
                        if (staticHeader) {
                            const sections = Array.from(document.querySelectorAll('section'));
                            const firstSection = sections.find((section) =>
                                Boolean(staticHeader.compareDocumentPosition(section) & Node.DOCUMENT_POSITION_FOLLOWING)
                            );

                            if (firstSection) {
                                // Match Builder.jsx exactly: overlay is only active when the first
                                // rendered Spark is semantically a hero/banner. A global overlay
                                // preference must not force a transparent/absolute header over an
                                // AI Flex/custom section that Builder currently renders in normal flow.
                                const firstType = String(firstSection.dataset.cosmicBlockType || firstSection.dataset.cosmicSemanticType || firstSection.dataset.type || '').toLowerCase();
                                const firstSectionIsBanner = firstType === 'hero' || firstType.includes('hero') || firstType.includes('banner');

                                if (!firstSectionIsBanner) {
                                    staticHeader.dataset.cosmicOverlayHeader = 'false';
                                    staticHeader.dataset.cosmicPremiumOverlayHeader = 'false';
                                    staticHeader.classList.remove(
                                        'cosmic-static-overlay-header',
                                        'cosmic-overlay-tone-light',
                                        'cosmic-overlay-tone-dark',
                                        'cosmic-overlay-cta-gradient',
                                        'cosmic-overlay-cta-primary',
                                        'absolute',
                                        'inset-x-0',
                                        'border-transparent',
                                        'bg-transparent',
                                        'shadow-none'
                                    );
                                    staticHeader.classList.add('sticky', 'top-0', 'bg-white', 'shadow-sm', 'border-b', 'border-slate-200');
                                    const flowHeight = Math.ceil(staticHeader.getBoundingClientRect().height || 0);
                                    document.documentElement.style.setProperty('--cosmic-header-flow-offset', `\${flowHeight}px`);
                                } else {
                                    firstSection.classList.add('cosmic-static-overlay-first-spark');

                                    // Premium overlay keeps the nav/logo high-contrast while the CTA
                                    // carries the active brand gradient. Do not revert the exported
                                    // header back to the legacy all-white CTA treatment at runtime.
                                    const useLightHeader = staticHeader.dataset.cosmicPremiumOverlayHeader === 'true';

                                    staticHeader.classList.toggle('cosmic-overlay-tone-light', useLightHeader);
                                    staticHeader.classList.toggle('cosmic-overlay-tone-dark', !useLightHeader);
                                    staticHeader.classList.remove('cosmic-overlay-cta-gradient');
                                    staticHeader.classList.add('cosmic-overlay-cta-primary');

                                    const syncOverlaySpacing = () => {
                                        const headerHeight = Math.ceil(staticHeader.getBoundingClientRect().height || 0);
                                        document.documentElement.style.setProperty('--cosmic-overlay-header-height', `\${headerHeight}px`);
                                    };

                                    syncOverlaySpacing();
                                    window.addEventListener('resize', syncOverlaySpacing);

                                    if (typeof ResizeObserver !== 'undefined') {
                                        const overlayResizeObserver = new ResizeObserver(syncOverlaySpacing);
                                        overlayResizeObserver.observe(staticHeader);
                                    }
                                }
                            }
                        }

                        const navRoot = document.querySelector('.cosmic-mobile-navigation');
                        const openButton = document.querySelector('.cosmic-mobile-menu-open');
                        const closeButton = navRoot?.querySelector('.cosmic-mobile-menu-close');
                        const overlay = navRoot?.querySelector('.cosmic-mobile-overlay');
                        const panel = navRoot?.querySelector('.cosmic-mobile-panel');

                        if (!navRoot || !openButton || !closeButton || !overlay || !panel) return;

                        let lastFocusedElement = null;

                        const setMenuOpen = (isOpen) => {
                            document.documentElement.classList.toggle('cosmic-mobile-nav-open', isOpen);
                            document.body.classList.toggle('cosmic-mobile-menu-locked', isOpen);
                            navRoot.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
                            openButton.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

                            if (isOpen) {
                                lastFocusedElement = document.activeElement;
                                window.setTimeout(() => closeButton.focus(), 60);
                            } else if (lastFocusedElement instanceof HTMLElement) {
                                lastFocusedElement.focus();
                            }
                        };

                        openButton.addEventListener('click', () => setMenuOpen(true));
                        closeButton.addEventListener('click', () => setMenuOpen(false));
                        overlay.addEventListener('click', () => setMenuOpen(false));

                        navRoot.querySelectorAll('[data-cosmic-mobile-link]').forEach((link) => {
                            link.addEventListener('click', () => setMenuOpen(false));
                        });

                        navRoot.querySelectorAll('.cosmic-mobile-submenu-toggle').forEach((toggle) => {
                            toggle.addEventListener('click', () => {
                                const submenuId = toggle.getAttribute('aria-controls');
                                const submenu = submenuId ? document.getElementById(submenuId) : null;
                                if (!submenu) return;

                                const expanded = toggle.getAttribute('aria-expanded') === 'true';
                                toggle.setAttribute('aria-expanded', expanded ? 'false' : 'true');
                                submenu.classList.toggle('hidden', expanded);
                            });
                        });

                        document.addEventListener('keydown', (event) => {
                            if (event.key === 'Escape' && openButton.getAttribute('aria-expanded') === 'true') {
                                setMenuOpen(false);
                            }
                        });

                        window.addEventListener('resize', () => {
                            if (window.innerWidth >= 768 && openButton.getAttribute('aria-expanded') === 'true') {
                                setMenuOpen(false);
                            }
                        });
                        };

                        if (document.readyState === 'loading') {
                            document.addEventListener('DOMContentLoaded', initCosmicStaticHeader, { once: true });
                        } else {
                            initCosmicStaticHeader();
                        }
                    })();
                </script>";
                break;

                case 'minimal_footer':
                $block = HeaderFooterVariantContract::normalizeFooter($block) ?? $block;
                if (($block['marketplace_variant'] ?? '') === 'harbor_coastal') {
