                $termsLabel = e($block['terms_label'] ?? 'Terms & Conditions');
                $termsUrl = e($block['terms_url'] ?? '/terms-and-conditions');
                $contact = is_array($block['contact'] ?? null) ? $block['contact'] : [];
                $contactEmail = e(trim((string)($contact['email'] ?? '')));
