                $footerPrimary = e((string) ($footerPalette['primary'] ?? '#243447'));
                $footerOnPrimary = e((string) ($footerPalette['on_primary'] ?? '#FFFFFF'));
                $footerHeading = e((string) ($footerPalette['heading'] ?? '#0F172A'));
