                    'heading_size'=>['--luna-heading-size','px'],'body_size'=>['--luna-body-size','px'],
                    'heading_line_height'=>['--luna-heading-line',''],'body_line_height'=>['--luna-body-line',''],
                    'letter_spacing'=>['--luna-letter-spacing','px'],'section_padding_y'=>['--luna-section-py','px'],
                    'section_padding_x'=>['--luna-section-px','px'],'content_gap'=>['--luna-content-gap','px'],
                    'card_radius'=>['--luna-card-radius','px'],'image_radius'=>['--luna-image-radius','px'],
                    'content_max_width'=>['--luna-content-max','px'],'section_min_height'=>['--luna-section-min-height','px'],
                ];
                foreach($safe as $key=>$value){[$var,$unit]=$map[$key];$vars.=$var.':'.$value.$unit.';';}
                if(isset($safe['card_radius']))$vars.='--cosmic-local-card-radius:'.$safe['card_radius'].'px;';
                if(isset($safe['heading_size'])){
                    $heading=(float)$safe['heading_size'];
                    $vars.='--cosmic-local-h1-size:'.$heading.'px;--cosmic-local-h2-size:'.$heading.'px;--cosmic-local-h3-size:'.max(16,min(72,$heading*.62)).'px;';
                }
                if(isset($safe['body_size'])){
                    $body=(float)$safe['body_size'];
                    $vars.='--cosmic-local-body-size:'.$body.'px;--cosmic-local-lead-size:'.max(13,min(34,$body*1.12)).'px;';
                }
                if(isset($safe['heading_line_height'])){
                    $line=(float)$safe['heading_line_height'];
                    $vars.='--cosmic-local-h1-line:'.$line.';--cosmic-local-h2-line:'.$line.';--cosmic-local-h3-line:'.$line.';';
                }
                if(isset($safe['body_line_height'])){
                    $bodyLine=(float)$safe['body_line_height'];
                    $vars.='--cosmic-local-body-line:'.$bodyLine.';--cosmic-local-lead-line:'.$bodyLine.';';
                }
                if(isset($safe['letter_spacing'])){
                    $tracking=(float)$safe['letter_spacing'];
                    $vars.='--cosmic-local-h1-tracking:'.$tracking.'px;--cosmic-local-h2-tracking:'.$tracking.'px;--cosmic-local-h3-tracking:'.$tracking.'px;';
                }
                if($heroNeedsDefaultPadding){
                    $vars.='--luna-section-py:100px;--luna-section-py-tablet:76px;--luna-section-py-mobile:56px;';
                }
                $align=in_array(($design['text_align']??''),['left','center','right'],true)?$design['text_align']:'';
                if($align!=='')$vars.='--luna-text-align:'.$align.';';
                $css="<style>.cosmic-luna-design-host>section,.cosmic-luna-design-host>div>section:first-child{padding-top:var(--luna-section-py,revert)!important;padding-bottom:var(--luna-section-py,revert)!important;padding-left:var(--luna-section-px,revert)!important;padding-right:var(--luna-section-px,revert)!important;min-height:var(--luna-section-min-height,revert)!important}.cosmic-luna-design-host[data-luna-design-typography='1'] h1{font-size:var(--cosmic-local-h1-size,revert)!important;line-height:var(--cosmic-local-h1-line,revert)!important;letter-spacing:var(--cosmic-local-h1-tracking,revert)!important;text-align:var(--luna-text-align,revert)!important;overflow-wrap:anywhere}.cosmic-luna-design-host[data-luna-design-typography='1'] h2{font-size:var(--cosmic-local-h2-size,revert)!important;line-height:var(--cosmic-local-h2-line,revert)!important;letter-spacing:var(--cosmic-local-h2-tracking,revert)!important;text-align:var(--luna-text-align,revert)!important;overflow-wrap:anywhere}.cosmic-luna-design-host[data-luna-design-typography='1'] p,.cosmic-luna-design-host[data-luna-design-typography='1'] li{font-size:var(--cosmic-local-body-size,revert)!important;line-height:var(--cosmic-local-body-line,revert)!important}.cosmic-luna-design-host img{border-radius:var(--luna-image-radius,revert)!important}@media(max-width:1024px){.cosmic-luna-design-host>section,.cosmic-luna-design-host>div>section:first-child{padding-top:var(--luna-section-py-tablet,min(var(--luna-section-py,72px),112px))!important;padding-bottom:var(--luna-section-py-tablet,min(var(--luna-section-py,72px),112px))!important}}@media(max-width:767px){.cosmic-luna-design-host[data-luna-design-typography='1'] h1{font-size:min(var(--cosmic-local-h1-size,var(--cosmic-type-h1-size)),64px)!important}.cosmic-luna-design-host[data-luna-design-typography='1'] h2{font-size:min(var(--cosmic-local-h2-size,var(--cosmic-type-h2-size)),64px)!important}.cosmic-luna-design-host[data-luna-design-typography='1'] h3{font-size:min(var(--cosmic-local-h3-size,var(--cosmic-type-h3-size)),64px)!important}.cosmic-luna-design-host>section,.cosmic-luna-design-host>div>section:first-child{padding-top:var(--luna-section-py-mobile,min(var(--luna-section-py,72px),112px))!important;padding-bottom:var(--luna-section-py-mobile,min(var(--luna-section-py,72px),112px))!important}}</style>";
                $typographyAttribute = $hasLegacyDesignTypography ? " data-luna-design-typography='1'" : '';
                $fragment="<div class='cosmic-luna-design-host' data-luna-design='1'{$typographyAttribute} style=\"".e($vars)."\">{$css}{$fragment}</div>";
                $html=substr($html,0,$fragmentStart).$fragment;
            }

            $localSection=is_array($block['luna_section_overrides']??null)?$block['luna_section_overrides']:[];
            if($fragment!=='' && $localSection!==[]){
                $sectionVars='';
                $map=[
                    'py'=>'--cosmic-local-section-py',
                    'py_top'=>'--cosmic-local-section-py-top',
                    'py_bottom'=>'--cosmic-local-section-py-bottom',
                    'px'=>'--cosmic-local-section-px',
                    'px_left'=>'--cosmic-local-section-px-left',
                    'px_right'=>'--cosmic-local-section-px-right',
                    'container'=>'--cosmic-local-section-container',
                    'gap'=>'--cosmic-local-section-gap',
                    'min_height'=>'--cosmic-local-section-min-height',
                ];
                foreach($map as $key=>$var){
                    if(!isset($localSection[$key])||!is_scalar($localSection[$key]))continue;
                    $raw=trim((string)$localSection[$key]);
                    if($raw===''||!preg_match('/^-?[0-9.]+(?:px|rem|em|%|vh|svh|vw)?$/i',$raw))continue;
                    $sectionVars.=$var.':'.$raw.';';
                }
                if($sectionVars!==''){
                    $fragment="<div class='cosmic-local-section-host' style=\"".e($sectionVars)."\">{$fragment}</div>";
                    $html=substr($html,0,$fragmentStart).$fragment;
                }
            }

            $localBackground=is_array($block['luna_background_overrides']??null)?$block['luna_background_overrides']:[];
            if($fragment!=='' && $localBackground!==[]){
                $backgroundVars='';
                $allowed=[
                    'gradient_from','gradient_via','gradient_to','gradient_glow','gradient_angle',
                    'overlay_light_strong','overlay_light_soft',
                    'overlay_primary_strong','overlay_primary_soft',
                    'overlay_cinematic_strong','overlay_cinematic_soft',
                ];
                foreach($localBackground as $key=>$value){
                    if(!in_array((string)$key,$allowed,true)||!is_scalar($value))continue;
                    $raw=trim((string)$value);
                    if($raw==='')continue;
                    if($key==='gradient_angle' && preg_match('/^-?[0-9.]+$/',$raw))$raw.='deg';
                    if(Str::startsWith((string)$key,'overlay_')){
                        if(!is_numeric($raw))continue;
                        $raw=(string)max(0,min(1,(float)$raw));
                    } elseif(Str::startsWith((string)$key,'gradient_') && $key!=='gradient_angle' && !preg_match('/^#[0-9A-Fa-f]{6}$/',$raw)){
                        continue;
                    }
                    $var='--cosmic-local-'.str_replace('_','-',(string)$key);
                    $backgroundVars.=$var.':'.$raw.';';
                }
                if($backgroundVars!==''){
                    $fragment="<div class='cosmic-local-background-host' style=\"".e($backgroundVars)."\">{$fragment}</div>";
                    $html=substr($html,0,$fragmentStart).$fragment;
                }
            }

            $localTypography=is_array($block['luna_typography_overrides']??null)?$block['luna_typography_overrides']:[];
            if($fragment!=='' && $localTypography!==[]){
                $allowedRoles=['h1','h2','h3','h4','h5','h6','card-title','stat-title','card-body','lead','body','eyebrow','small','badge','meta','button'];
                $allowedProps=['size','line','weight','tracking'];
                $localVars='';
                foreach($localTypography as $key=>$value){
                    if(!is_scalar($value))continue;
                    if(!preg_match('/^(h1|h2|h3|h4|h5|h6|card-title|stat-title|card-body|lead|body|eyebrow|small|badge|meta|button)_(size|line|weight|tracking)$/',(string)$key,$m))continue;
                    if(!in_array($m[1],$allowedRoles,true)||!in_array($m[2],$allowedProps,true))continue;
                    $raw=trim((string)$value);
                    $safeScalar=preg_match('/^-?[0-9.]+(?:px|rem|em|%)?$/i',$raw)===1;
                    $safeClamp=$m[2]==='size' && preg_match('/^clamp\(\s*[0-9.]+(?:px|rem)\s*,\s*[0-9.]+vw\s*,\s*[0-9.]+(?:px|rem)\s*\)$/i',$raw)===1;
                    if($raw===''||(!$safeScalar&&!$safeClamp))continue;
                    $localVars.='--cosmic-local-'.$m[1].'-'.$m[2].':'.$raw.';';
                }
                if($localVars!==''){
                    $fragment="<div class='cosmic-local-typography-host' style=\"".e($localVars)."\">{$fragment}</div>";
                    $html=substr($html,0,$fragmentStart).$fragment;
                }
            }

            $localComponent=is_array($block['luna_component_overrides']??null)?$block['luna_component_overrides']:[];
            if($fragment!=='' && $localComponent!==[]){
                $componentVars='';
                $componentAttributes="data-cosmic-component-overrides='1'";
                $componentMap=[
                    'button_height'=>'--cosmic-local-button-height',
                    'button_px'=>'--cosmic-local-button-px',
                    'button_radius'=>'--cosmic-local-button-radius',
                    'button_weight'=>'--cosmic-local-button-weight',
                    'input_height'=>'--cosmic-local-input-height',
                    'input_px'=>'--cosmic-local-input-px',
                    'input_radius'=>'--cosmic-local-input-radius',
                    'card_radius'=>'--cosmic-local-card-radius',
                    'card_padding'=>'--cosmic-local-card-padding',
                    'image_radius'=>'--cosmic-local-image-radius',
                    'modal_radius'=>'--cosmic-local-modal-radius',
                    'section_radius'=>'--cosmic-local-section-radius',
                ];
                foreach($componentMap as $key=>$var){
                    if(!isset($localComponent[$key])||!is_scalar($localComponent[$key]))continue;
                    $raw=trim((string)$localComponent[$key]);
                    if($raw===''||!preg_match('/^-?[0-9.]+(?:px|rem|em|%)?$/i',$raw))continue;
                    $componentVars.=$var.':'.$raw.';';
                    if($key==='card_radius')$componentVars.='--luna-card-radius:'.$raw.';';
                    if($key==='image_radius')$componentVars.='--luna-image-radius:'.$raw.';';
                }
                if(($localComponent['card_surface']??null)==='dark'){
                    $componentVars.='--cosmic-local-card-bg:var(--cosmic-bg-primary-surface,var(--cosmic-brand-primary,#0f172a));';
                    $componentVars.='--cosmic-local-card-heading:var(--cosmic-color-on-dark,#f8fafc);';
                    $componentVars.='--cosmic-local-card-text:color-mix(in srgb,var(--cosmic-color-on-dark,#f8fafc) 82%,transparent);';
                    $componentVars.='--cosmic-local-card-border:color-mix(in srgb,var(--cosmic-color-on-dark,#f8fafc) 24%,transparent);';
                    $componentAttributes.=" data-cosmic-card-surface='dark'";
                }
                if($componentVars!==''){
                    $fragment="<div class='cosmic-local-component-host cosmic-render-shell' {$componentAttributes} style=\"".e($componentVars)."\">{$fragment}</div>";
                    $html=substr($html,0,$fragmentStart).$fragment;
                }
            }

            if ($fragment !== '' && preg_match('/<section\b/i', $fragment)) {
                // Preserve Builder's exact semantic state so white/surface rhythm
                // survives Preview, Export and Live instead of collapsing to light.
                $semanticTheme = in_array($blockTheme, ['primary', 'white', 'surface'], true)
                    ? $blockTheme
                    : ($blockTheme === 'light' ? 'light' : 'primary');
                $semanticTheme = e($semanticTheme);
                $implementationType = (string) ($block['type'] ?? '');
                $semanticRawType = $implementationType === 'luna_custom_section'
                    ? (string) ($block['semantic_type'] ?? $block['category'] ?? $implementationType)
                    : $implementationType;
                $semanticType = e($semanticRawType);
                $implementationTypeAttr = e($implementationType);
                $semanticIndex = (int) $index;
                $renderContractVersion = e(self::renderContractVersion());
                $tailwindSchemaState = app(\App\Services\SparkTailwindSchemaContract::class)->isSchemaBacked($block)
                    ? 'schema_backed'
                    : 'legacy_fallback';
                $taggedFragment = preg_replace(
                    '/<section(?![^>]*data-cosmic-spark)/i',
                    "<section data-cosmic-spark='1' data-cosmic-layout-contract='premium-v1' data-cosmic-render-contract='{$renderContractVersion}' data-cosmic-tailwind-schema='{$tailwindSchemaState}' data-cosmic-block-index='{$semanticIndex}' data-cosmic-resolved-theme='{$semanticTheme}' data-cosmic-block-type='{$semanticType}' data-cosmic-implementation-type='{$implementationTypeAttr}'",
                    $fragment,
                    1
                );

                if (is_string($taggedFragment)) {
                    $html = substr($html, 0, $fragmentStart) . $taggedFragment;
                }
            }
        }
        // Each compiled block root is tagged inside the block loop above.
        // Do NOT tag nested <section> elements globally: export CSS would otherwise
        // apply Spark-level spacing to internal sections and diverge from Builder.

        // Centralized Cosmic typography contract. Existing Sparks are migrated to
        // these semantic roles in the next pass; keeping this stylesheet in the
        // compiler now guarantees the same token contract in Preview/Export/Live.
        $typographyCss = <<<'CSS'
