    /**
     * Brightline Dental owns a calm, image-led clinic design kit.  Marketplace
     * Dental Sparks are Builder-only React components, so export/live must have
     * an equivalent static renderer instead of falling through to an empty
     * generic Spark branch.
     */
    private static function marketplaceBrightlineHtml(string $type, array $block): string
    {
        $id = 'brightline-' . substr(md5($type . json_encode($block)), 0, 10);
        $text = static fn ($value): string => e((string) $value);
        $url = static fn ($value): string => e((string) ($value ?: '#'));
        $image = static fn ($value): string => e(self::staticAssetUrl((string) $value));
        $items = static fn ($value, array $fallback = []): array => is_array($value) && count($value) ? array_values($value) : $fallback;

        $baseCss = <<<CSS
<style>
#{$id}{--bd-ink:#17304a;--bd-navy:#10263b;--bd-blue:#2f86a6;--bd-blue2:#54a9c2;--bd-mint:#dff1ed;--bd-mist:#eef7f8;--bd-paper:#fbfdfd;--bd-line:#d9e8eb;--bd-muted:#667d88;--bd-peach:#f5e5dc;color:var(--bd-ink);font-family:Inter,ui-sans-serif,system-ui,sans-serif}
#{$id} *{box-sizing:border-box}#{$id} img{display:block;width:100%;height:100%;object-fit:cover}#{$id} a{text-decoration:none}
#{$id} .bd-shell{width:min(1380px,calc(100% - 48px));margin:0 auto}#{$id} .bd-eyebrow{display:block;color:var(--bd-blue);font-size:10px;font-weight:900;letter-spacing:.22em;text-transform:uppercase}
#{$id} .bd-h1,#{$id} .bd-h2,#{$id} .bd-h3{display:block;margin:0;color:var(--bd-ink);font-weight:900;letter-spacing:-.05em}#{$id} .bd-h2{font-size:clamp(40px,5vw,68px);line-height:1.01}#{$id} .bd-h3{font-size:24px;line-height:1.1}
#{$id} .bd-copy{color:var(--bd-muted);font-size:16px;line-height:1.9}#{$id} .bd-btn{display:inline-flex;min-height:50px;align-items:center;justify-content:center;border-radius:999px;padding:0 28px;font-size:14px;font-weight:900}#{$id} .bd-btn-primary{background:var(--bd-navy);color:#fff}#{$id} .bd-btn-secondary{border:1px solid var(--bd-line);background:#fff;color:var(--bd-ink)}
#{$id} .bd-grid{display:grid;gap:20px}@media(max-width:820px){#{$id} .bd-shell{width:min(100% - 32px,1380px)}}
</style>
CSS;

        if ($type === 'marketplace_dental_hero') {
            $eyebrow=$text($block['eyebrow']??'MODERN DENTISTRY · GENTLE CARE');$heading=$text($block['heading']??'Dental care that feels');$accent=$text($block['accent_heading']??'clear, calm, and personal.');$copy=$text($block['text']??'Thoughtful dentistry, modern technology, and a team that takes the time to make every visit feel easier.');$pLabel=$text($block['primary_label']??'Book an Appointment');$pUrl=$url($block['primary_url']??'/contact');$sLabel=$text($block['secondary_label']??'Explore Treatments');$sUrl=$url($block['secondary_url']??'/treatments');$src=$image($block['image_url']??'https://images.unsplash.com/photo-1609840114035-3c981b782dfe?auto=format&fit=crop&w=1800&q=88');$trust=$text($block['trust_label']??'New patients welcome');$trustText=$text($block['trust_text']??'Same-week appointments available');
            $css=<<<CSS
<style>#{$id}{padding:20px 0;background:var(--bd-paper)}#{$id} .bd-hero{position:relative;overflow:hidden;min-height:720px;background:var(--bd-mist)}#{$id} .bd-hero:before{content:"";position:absolute;left:-90px;top:-110px;width:330px;height:330px;border-radius:50%;background:var(--bd-mint);filter:blur(55px);opacity:.9}#{$id} .bd-hero-grid{position:relative;display:grid;grid-template-columns:.92fr 1.08fr;min-height:720px}#{$id} .bd-hero-copy{display:flex;align-items:center;padding:70px clamp(36px,5vw,82px)}#{$id} .bd-pill{display:inline-flex;align-items:center;gap:10px;margin-bottom:28px;border:1px solid var(--bd-line);border-radius:999px;background:rgba(255,255,255,.78);padding:9px 14px}#{$id} .bd-dot{width:8px;height:8px;border-radius:50%;background:var(--bd-blue2)}#{$id} .bd-h1{font-size:clamp(52px,6vw,98px);line-height:.92}#{$id} .bd-accent{display:block;margin-top:4px;color:var(--bd-blue);font-family:Georgia,serif;font-size:clamp(48px,5.6vw,91px);font-style:italic;line-height:.95;letter-spacing:-.05em}#{$id} .bd-hero-copy .bd-copy{max-width:620px;margin-top:28px}#{$id} .bd-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px}#{$id} .bd-media{position:relative;min-height:520px;margin:20px 20px 20px 0;overflow:hidden;border-radius:34px}#{$id} .bd-trust{position:absolute;left:-34px;bottom:36px;max-width:290px;border:1px solid var(--bd-line);border-radius:22px;background:rgba(255,255,255,.94);padding:20px;box-shadow:0 24px 70px rgba(23,48,74,.18)}#{$id} .bd-trust strong{display:block;color:var(--bd-blue);font-size:11px;letter-spacing:.12em;text-transform:uppercase}#{$id} .bd-trust span{display:block;margin-top:8px;color:var(--bd-ink);font-size:14px;font-weight:800;line-height:1.5}@media(max-width:980px){#{$id} .bd-hero-grid{grid-template-columns:1fr}#{$id} .bd-media{margin:0 20px 20px;min-height:460px}#{$id} .bd-trust{left:24px}#{$id} .bd-hero{min-height:auto}}@media(max-width:560px){#{$id} .bd-hero-copy{padding:54px 24px}#{$id} .bd-media{min-height:390px;margin:0 12px 12px}#{$id} .bd-trust{right:18px;left:18px;max-width:none}}</style>
CSS;
            return "<section id='{$id}' class='marketplace-brightline'><div class='bd-shell bd-hero'><div class='bd-hero-grid'><div class='bd-hero-copy'><div><div class='bd-pill'><span class='bd-dot'></span><span class='bd-eyebrow'>{$eyebrow}</span></div><h1 class='bd-h1'>{$heading}</h1><span class='bd-accent'>{$accent}</span><p class='bd-copy'>{$copy}</p><div class='bd-actions'><a class='bd-btn bd-btn-primary' href='{$pUrl}'>{$pLabel}</a><a class='bd-btn bd-btn-secondary' href='{$sUrl}'>{$sLabel}</a></div></div></div><div class='bd-media'><img src='{$src}' alt='' loading='eager'><div class='bd-trust'><strong>{$trust}</strong><span>{$trustText}</span></div></div></div></div>{$baseCss}{$css}</section>";
        }

        if ($type === 'marketplace_dental_treatments') {
            $defaults=[['icon'=>'01','title'=>'General Dentistry','text'=>'Check-ups, cleans, fillings, and preventive care for healthy smiles at every age.'],['icon'=>'02','title'=>'Cosmetic Dentistry','text'=>'Whitening, veneers, and tailored smile improvements with a natural, considered approach.'],['icon'=>'03','title'=>'Emergency Dental','text'=>'Prompt support for pain, swelling, broken teeth, and urgent dental concerns.'],['icon'=>'04','title'=>'Preventive Care','text'=>'Practical routines and regular care designed to protect your long-term oral health.']];
            $raw=$items($block['items']??null,$defaults);$cards='';foreach(array_slice($raw,0,6) as $i=>$item){if(!is_array($item))continue;$num=$text($item['icon']??str_pad((string)($i+1),2,'0',STR_PAD_LEFT));$title=$text($item['title']??'Treatment');$copy=$text($item['text']??'');$bg=$i%2?'#fbfdfd':'#eef7f8';$cards.="<article class='bd-treatment' style='background:{$bg}'><span class='bd-eyebrow'>{$num}</span><div><h3 class='bd-h3'>{$title}</h3><p class='bd-copy'>{$copy}</p></div></article>";}
            $eyebrow=$text($block['eyebrow']??'TREATMENTS');$heading=$text($block['heading']??'Everything you need for a healthier, more confident smile.');$copy=$text($block['text']??'From preventive care to cosmetic and urgent dentistry, treatment is explained clearly and tailored to you.');
            $css=<<<CSS
<style>#{$id}{padding:108px 0;background:#fff}#{$id} .bd-head{display:grid;grid-template-columns:1.1fr .7fr;gap:50px;align-items:end}#{$id} .bd-head .bd-copy{margin:0}#{$id} .bd-h2{margin-top:18px}#{$id} .bd-treatment-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:54px}#{$id} .bd-treatment{display:flex;min-height:330px;flex-direction:column;justify-content:space-between;border:1px solid var(--bd-line);border-radius:28px;padding:28px}#{$id} .bd-treatment .bd-copy{margin:15px 0 0;font-size:14px;line-height:1.8}@media(max-width:1050px){#{$id} .bd-treatment-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){#{$id}{padding:78px 0}#{$id} .bd-head{grid-template-columns:1fr}#{$id} .bd-treatment-grid{grid-template-columns:1fr}}</style>
CSS;
            return "<section id='{$id}' class='marketplace-brightline'><div class='bd-shell'><div class='bd-head'><div><span class='bd-eyebrow'>{$eyebrow}</span><h2 class='bd-h2'>{$heading}</h2></div><p class='bd-copy'>{$copy}</p></div><div class='bd-treatment-grid'>{$cards}</div></div>{$baseCss}{$css}</section>";
        }

        if ($type === 'marketplace_dental_comfort') {
