    /**
     * Stonebridge Construction static renderer.  The Marketplace Stone blocks
     * are bespoke React components in Builder, so publish/export needs a
     * matching industrial renderer rather than generic Spark fall-through.
     */
    private static function marketplaceStonebridgeHtml(string $type, array $block): string
    {
        $id = 'stonebridge-' . substr(md5($type . json_encode($block)), 0, 10);
        $text = static fn ($value): string => e((string) $value);
        $url = static fn ($value): string => e((string) ($value ?: '#'));
        $image = static fn ($value): string => e(self::staticAssetUrl((string) $value));
        $arr = static fn ($value, array $fallback = []): array => is_array($value) && count($value) ? array_values($value) : $fallback;
        $eyebrow = $text($block['eyebrow'] ?? 'STONEBRIDGE CONSTRUCTION');
        $heading = $text($block['heading'] ?? 'Built for certainty.');
        $copy = $text($block['text'] ?? 'Disciplined planning, experienced teams, and accountable delivery.');
        $base = <<<CSS
<style>
#{$id}{--st-ink:#17191b;--st-black:#0f1112;--st-charcoal:#24282b;--st-graphite:#343a3d;--st-orange:#e66b2f;--st-orange2:#f48a4d;--st-sand:#efe9df;--st-paper:#f6f3ed;--st-line:#cfc8bd;--st-muted:#74716b;color:var(--st-ink);font-family:Inter,ui-sans-serif,system-ui,sans-serif}
#{$id} *{box-sizing:border-box}#{$id} img{display:block;width:100%;height:100%;object-fit:cover;border-radius:0!important}#{$id} a{text-decoration:none}#{$id} .st-shell{width:min(1420px,calc(100% - 48px));margin:auto}#{$id} .st-eye{color:var(--st-orange);font-size:10px;font-weight:900;letter-spacing:.24em;text-transform:uppercase}#{$id} .st-h1,#{$id} .st-h2,#{$id} .st-h3{margin:0;font-weight:950;text-transform:uppercase;letter-spacing:-.055em}#{$id} .st-h2{font-size:clamp(42px,5.4vw,78px);line-height:.9}#{$id} .st-h3{font-size:24px;line-height:1.04}#{$id} .st-copy{color:var(--st-muted);font-size:16px;line-height:1.85}#{$id} .st-btn{display:inline-flex;min-height:50px;align-items:center;justify-content:center;padding:0 28px;background:var(--st-orange);color:#fff;font-size:13px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}#{$id} .st-grid{display:grid}@media(max-width:760px){#{$id} .st-shell{width:min(100% - 32px,1420px)}}
</style>
CSS;

        if ($type === 'marketplace_stone_hero') {
            $accent=$text($block['accent_heading']??'BUILT TO DELIVER.');$src=$image($block['image_url']??'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1800&q=88');$p=$text($block['primary_label']??'Request a Quote');$pu=$url($block['primary_url']??'/contact');$s=$text($block['secondary_label']??'View Projects');$su=$url($block['secondary_url']??'/projects');$badge=$text($block['badge']??'Commercial · Residential · Fit-outs');
            return "<section id='{$id}' style='padding:16px;background:#0f1112'><div class='st-shell' style='max-width:1540px;position:relative;min-height:720px;overflow:hidden;border:1px solid #383b3d'><img src='{$src}' alt='' loading='eager' style='position:absolute;inset:0'><div style='position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,17,18,.98),rgba(15,17,18,.9) 44%,rgba(15,17,18,.18))'></div><div style='position:relative;z-index:2;min-height:720px;display:flex;align-items:center;padding:72px clamp(28px,6vw,96px);color:white'><div style='max-width:900px'><span class='st-eye'>{$eyebrow}</span><h1 class='st-h1' style='margin-top:25px;font-size:clamp(60px,8vw,132px);line-height:.8'>{$heading}</h1><div style='margin-top:8px;color:var(--st-orange2);font-size:clamp(46px,6vw,100px);font-weight:950;line-height:.84;text-transform:uppercase;letter-spacing:-.06em'>{$accent}</div><p style='max-width:690px;margin:28px 0 0;color:rgba(255,255,255,.68);font-size:18px;line-height:1.75'>{$copy}</p><div style='display:flex;gap:12px;flex-wrap:wrap;margin-top:32px'><a class='st-btn' href='{$pu}'>{$p}</a><a href='{$su}' style='display:inline-flex;min-height:50px;align-items:center;padding:0 28px;border:1px solid rgba(255,255,255,.35);color:#fff;font-size:13px;font-weight:900;text-transform:uppercase'>{$s}</a></div></div></div><div style='position:absolute;right:0;bottom:0;z-index:3;padding:18px 26px;border:1px solid rgba(255,255,255,.2);background:rgba(15,17,18,.84);color:#ddd;font-size:10px;font-weight:900;letter-spacing:.16em;text-transform:uppercase'>{$badge}</div></div>{$base}</section>";
