        $base = "<style>#{$id}{--cf-navy:#102a43;--cf-blue:#0b78c8;--cf-aqua:#28b7c8;--cf-ice:#eef8fb;--cf-muted:#5f7180;--cf-line:#cfe1e8;--cf-lime:#d9f45a;color:var(--cf-navy);font-family:Inter,ui-sans-serif,system-ui,sans-serif}#{$id} *{box-sizing:border-box}#{$id} img{display:block;width:100%;height:100%;object-fit:cover;border-radius:0!important}#{$id} a{text-decoration:none}#{$id} .cf-shell{width:min(1400px,calc(100% - 48px));margin:auto}#{$id} .cf-eye{font-size:10px;font-weight:900;letter-spacing:.2em;text-transform:uppercase;color:var(--cf-blue)}#{$id} .cf-h2{margin:18px 0 0;font-size:clamp(42px,5.4vw,76px);line-height:.98;letter-spacing:-.05em;font-weight:900}#{$id} .cf-copy{color:var(--cf-muted);font-size:16px;line-height:1.85}#{$id} .cf-btn{display:inline-flex;min-height:50px;align-items:center;padding:0 28px;background:var(--cf-lime);color:var(--cf-navy);font-size:13px;font-weight:900}@media(max-width:760px){#{$id} .cf-shell{width:min(100% - 32px,1400px)}}</style>";

        if ($type === 'marketplace_clearflow_hero') {
            $accent=$text($block['accent_heading']??'Done properly.');$img=$image($block['image_url']??'');$p=$text($block['primary_label']??'Call a Plumber');$pu=$url($block['primary_url']??'tel:+61255500314');$s=$text($block['secondary_label']??'Book Online');$su=$url($block['secondary_url']??'/contact');$badge=$text($block['badge']??'Same-day help available');
            return "<section id='{$id}' style='padding:16px;background:var(--cf-ice)'><div style='max-width:1540px;margin:auto;display:grid;grid-template-columns:1.02fr .98fr;min-height:650px;background:var(--cf-navy)'><div style='padding:76px;color:#fff;display:flex;align-items:center'><div><span style='color:var(--cf-aqua);font-size:10px;font-weight:900;letter-spacing:.2em'>{$eye}</span><h1 style='font-size:clamp(58px,7vw,112px);line-height:.88;letter-spacing:-.06em;margin:22px 0 0'>{$heading}<br><span style='color:var(--cf-lime)'>{$accent}</span></h1><p style='color:rgba(255,255,255,.7);line-height:1.8;max-width:620px'>{$copy}</p><div style='display:flex;gap:12px;flex-wrap:wrap'><a class='cf-btn' href='{$pu}'>{$p}</a><a href='{$su}' style='display:inline-flex;align-items:center;padding:0 26px;border:1px solid rgba(255,255,255,.35);color:#fff;font-weight:900'>{$s}</a></div></div></div><div style='position:relative;min-height:430px'><img src='{$img}' alt=''><div style='position:absolute;left:24px;bottom:24px;background:#fff;padding:16px 20px;font-weight:900'>{$badge}</div></div></div>{$base}<style>@media(max-width:800px){#{$id}>div{grid-template-columns:1fr!important}#{$id}>div>div:first-child{padding:48px 28px!important}}</style></section>";
        }
        if ($type === 'marketplace_clearflow_services') {
