    /** Harbor & Key global footer renderer used by published/static output. */
    private static function harborCoastalFooterHtml(array $block): string
    {
        $e = static fn ($value): string => e((string) $value);
        $brand = $e($block['logo_text'] ?? $block['brand'] ?? 'HARBOR & KEY REALTY');
        $mega = is_array($block['mega_footer'] ?? null) ? $block['mega_footer'] : [];
        $tagline = $e($mega['tagline'] ?? $block['tagline'] ?? $block['description'] ?? 'Connecting you to exceptional properties and experiences across Cebu and beyond.');
        $columns = is_array($mega['columns'] ?? null) ? array_slice(array_values($mega['columns']), 0, 4) : [];
        $newsletter = is_array($block['newsletter'] ?? null) ? $block['newsletter'] : [];
        $socials = is_array($block['social_links'] ?? null) ? array_slice(array_values($block['social_links']), 0, 6) : [];
        $columnHtml = '';
        foreach ($columns as $column) {
            if (! is_array($column)) continue;
            $title = $e($column['title'] ?? 'Explore');
            $items = is_array($column['items'] ?? null) ? array_slice(array_values($column['items']), 0, 6) : [];
            $links = '';
            foreach ($items as $item) {
                if (! is_array($item)) continue;
                $label = $e($item['label'] ?? 'Link');
                $url = $e($item['url'] ?? '#');
                $links .= "<a href='{$url}'>{$label}</a>";
            }
            $columnHtml .= "<div class='hkf-col'><p>{$title}</p><div>{$links}</div></div>";
        }
        $socialHtml = '';
        foreach ($socials as $social) {
            if (! is_array($social)) continue;
            $label = $e($social['label'] ?? 'Social');
            $url = $e($social['url'] ?? '#');
            $socialHtml .= "<a href='{$url}'>{$label}</a>";
        }
        if ($socialHtml === '') $socialHtml = '<span>f</span><span>◎</span><span>in</span><span>▶</span>';
        $newsletterTitle = $e($newsletter['title'] ?? 'Newsletter');
        $newsletterText = $e($newsletter['text'] ?? 'Be the first to get the latest property listings and news.');
        $newsletterPlaceholder = $e($newsletter['placeholder'] ?? 'Enter your email');
        $newsletterButton = $e($newsletter['button_label'] ?? 'SUBSCRIBE');
        $copy = $e($block['copyright'] ?? ('© '.date('Y').' Harbor & Key Realty. All Rights Reserved.'));
        $privacyLabel = $e($block['privacy_label'] ?? 'Privacy Policy');
        $privacyUrl = $e($block['privacy_url'] ?? '/privacy-policy');
        $termsLabel = $e($block['terms_label'] ?? 'Terms of Use');
        $termsUrl = $e($block['terms_url'] ?? '/terms-and-conditions');
        return "<section class='hkf-shell' data-marketplace-footer='harbor_coastal'><div class='hkf-grid'><div class='hkf-brand'><div class='hkf-brandline'><span class='hkf-key'>⌂</span><span><strong>HARBOR &amp; KEY</strong><small>REALTY</small></span></div><p>{$tagline}</p><b>FOLLOW US</b><div class='hkf-social'>{$socialHtml}</div></div>{$columnHtml}<div class='hkf-news'><p>{$newsletterTitle}</p><span>{$newsletterText}</span><input type='email' placeholder='{$newsletterPlaceholder}'><button type='button'>{$newsletterButton}</button></div></div></section><footer class='hkf-legal'><span>{$copy}</span><span><a href='{$privacyUrl}'>{$privacyLabel}</a><a href='{$termsUrl}'>{$termsLabel}</a><a href='/sitemap.xml'>Sitemap</a></span></footer><style>
.hkf-shell,.hkf-legal{box-sizing:border-box;width:100%;background:#071f3d;color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.hkf-shell{padding:46px 50px;border-bottom:1px solid rgba(255,255,255,.1)}.hkf-grid{display:grid;grid-template-columns:1.22fr .68fr .82fr .9fr .9fr 1.02fr;gap:28px;width:100%;max-width:1536px;margin:auto}.hkf-brandline{display:flex;align-items:center;gap:10px}.hkf-key{color:#c6a052;font-size:34px}.hkf-brandline strong{display:block;font:700 17px/1 Georgia,'Times New Roman',serif;letter-spacing:.055em}.hkf-brandline small{display:block;margin-top:6px;color:#c6a052;font-size:8px;font-weight:900;letter-spacing:.42em;text-align:center}.hkf-brand>p{max-width:300px;margin:16px 0 0;color:rgba(255,255,255,.62);font-size:11px;line-height:1.8}.hkf-brand>b{display:block;margin-top:24px;color:rgba(255,255,255,.48);font-size:9px;letter-spacing:.16em}.hkf-social{display:flex;flex-wrap:wrap;gap:15px;margin-top:12px}.hkf-social a,.hkf-social span{color:rgba(255,255,255,.72);font-size:10px}.hkf-col>p,.hkf-news>p{margin:0;color:rgba(255,255,255,.92);font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.hkf-col>div{display:grid;gap:9px;margin-top:16px}.hkf-col a{color:rgba(255,255,255,.58);font-size:10px;line-height:1.55;text-decoration:none}.hkf-news>span{display:block;margin-top:16px;color:rgba(255,255,255,.58);font-size:10px;line-height:1.7}.hkf-news input{width:100%;min-height:38px;margin-top:15px;border:1px solid rgba(255,255,255,.28);border-radius:2px;background:transparent;padding:0 10px;color:#fff;font-size:10px}.hkf-news button{width:100%;min-height:38px;margin-top:8px;border:0;border-radius:2px;background:#c6a052;color:#fff;font-size:9px;font-weight:900}.hkf-legal{display:flex;justify-content:space-between;gap:20px;padding:18px 50px;border-top:1px solid rgba(255,255,255,.08);color:#8ea1b9;font-size:9px}.hkf-legal>span:last-child{display:flex;flex-wrap:wrap;gap:20px}.hkf-legal a{color:#8ea1b9;text-decoration:none}@media(max-width:1200px){.hkf-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.hkf-shell{padding:40px 24px}.hkf-grid{grid-template-columns:1fr}.hkf-legal{flex-direction:column;padding:18px 24px}}
</style>";
    }

